package br.com.onda;
import org.json.*;
import org.junit.Test;
import static org.junit.Assert.*;
public class TiktokPageTest {
 static final String ID="7412345678901234567",MEDIA="https://v16.example.com/clip.mp4?token=abc&expires=999";
 static JSONObject item()throws Exception{return new JSONObject().put("id",ID).put("desc","Aula de violão").put("video",new JSONObject().put("playAddr",MEDIA));}
 static String universal(JSONObject item)throws Exception{return "<html><script type='application/json' id='__UNIVERSAL_DATA_FOR_REHYDRATION__'>"+new JSONObject().put("__DEFAULT_SCOPE__",new JSONObject().put("webapp.video-detail",new JSONObject().put("statusCode",0).put("itemInfo",new JSONObject().put("itemStruct",item))))+"</script></html>";}
 @Test public void currentPublicPayloadAndOptions()throws Exception{TiktokPage.Clip clip=TiktokPage.parse(universal(item()),ID);assertEquals("Aula de violão",clip.title);assertEquals(MEDIA,clip.video);YoutubeDownloads.Result result=MediaDownloads.tiktok(clip,"https://www.tiktok.com/@onda/video/"+ID);assertEquals(3,result.options.size());assertTrue(result.options.get(0).original);assertEquals("mp4",result.options.get(0).extension);assertEquals("mp3",result.options.get(1).extension);assertFalse(result.options.get(1).original);assertEquals(MEDIA,result.options.get(1).first);assertEquals("https://www.tiktok.com/@onda/video/"+ID,result.options.get(1).referer);}
 @Test public void legacyExactItemAndOfficialDownload()throws Exception{JSONObject item=item();item.getJSONObject("video").put("downloadAddr",new JSONObject().put("UrlList",new JSONArray().put(MEDIA+"&watermark=1")));String html="<script id=\"SIGI_STATE\">"+new JSONObject().put("ItemModule",new JSONObject().put(ID,item).put("7411111111111111111",new JSONObject().put("video",new JSONObject().put("playAddr","https://wrong.example.com/recommended.mp4")) ))+"</script>";assertEquals(MEDIA+"&watermark=1",TiktokPage.parse(html,ID).video);}
 @Test public void addressArraysAndJsonEscaping()throws Exception{JSONObject item=item();item.getJSONObject("video").put("playAddr",new JSONArray().put(new JSONObject().put("src",MEDIA)));assertEquals(MEDIA,TiktokPage.parse(universal(item),ID).video);assertEquals("",TiktokPage.address("https://127.0.0.1/a.mp4"));assertEquals("",TiktokPage.address("javascript:alert(1)"));assertEquals("",TiktokPage.address("https://www.tiktok.com/login"));}
 @Test public void rejectPrivateDifferentPostPhotosAndChallenge()throws Exception{for(JSONObject item:new JSONObject[]{item().put("privateItem",true),item().put("id","7411111111111111111"),item().put("imagePost",new JSONObject())})try{TiktokPage.parse(universal(item),ID);fail();}catch(Exception expected){}try{TiktokPage.parse("<html>Please verify you are human</html>",ID);fail();}catch(Exception expected){assertTrue(expected.getMessage().contains("verificação"));}}
}
